WITH exploded AS (SELECT id, service, host, log_ts, level, latency_ms, status_code, k, v FROM app_logs LATERAL VIEW EXPLODE(context) e AS k, v), metrics AS (SELECT *, AVG(latency_ms) OVER w_part running_avg_latency_ms, SUM(latency_ms) OVER w_part running_sum_latency_ms, MAX(latency_ms) OVER w_part running_max_latency_ms FROM exploded WHERE level NOT IN ('WARN', 'INFO', 'ERROR') WINDOW w_part AS (PARTITION BY level ORDER BY status_code ASC, id ASC, k ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), with_windows AS (SELECT *, LAG(running_max_latency_ms) OVER (PARTITION BY service ORDER BY status_code ASC, id ASC, k ASC) prev_running_max_latency_ms, LEAD(running_sum_latency_ms) OVER (PARTITION BY service ORDER BY status_code ASC, id ASC, k ASC) next_running_sum_latency_ms, LAG(running_sum_latency_ms) OVER (PARTITION BY service ORDER BY status_code ASC, id ASC, k ASC) prev_running_sum_latency_ms, ROW_NUMBER() OVER (PARTITION BY service ORDER BY status_code ASC, id ASC, k ASC) row_seq, AVG(latency_ms) OVER (PARTITION BY service ORDER BY running_max_latency_ms ASC, id ASC, k ASC ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) latency_ms_avg_5_prior FROM metrics), cleaned AS (SELECT id, service, level, latency_ms, status_code, k, v, running_avg_latency_ms, prev_running_max_latency_ms, prev_running_sum_latency_ms, row_seq, latency_ms_avg_5_prior, CASE WHEN level = 'ERROR' THEN 1 ELSE 0 END is_error, ROUND(prev_running_sum_latency_ms * 100, 2) adjusted_prev_running_sum_latency_ms FROM with_windows WHERE log_ts >= DATE '2025-06-01' AND running_avg_latency_ms < 2100) SELECT id, service, level, latency_ms, k, running_avg_latency_ms, prev_running_max_latency_ms, row_seq, is_error, CASE WHEN k RLIKE '^(version|region)$' THEN 'GROUP_B' WHEN k RLIKE '^(trace)$' THEN 'OTHER_ZONE' ELSE 'EXTENDED' END AS k_zone FROM cleaned
